import React, { useState, useEffect } from 'react';
import { useAuthStore } from '../../store/authStore';
import { useThemeStore } from '../../store/themeStore';
import { Menu, X, LogOut, Globe, Moon, Sun } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';

export default function Header() {
    const { user, logout } = useAuthStore();
    const navigate = useNavigate();
    const [menuOpen, setMenuOpen] = useState(false);
    const [language, setLanguage] = useState('en');

    const handleLogout = () => {
        logout();
        navigate('/login');
    };

    return (
        <header className="bg-white shadow-md sticky top-0 z-40">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div className="flex justify-between items-center h-16">
                    {/* Logo */}
                    <Link to="/dashboard" className="flex items-center gap-2">
                        <div className="w-8 h-8 bg-green-600 rounded-lg flex items-center justify-center">
                            <span className="text-white font-bold">AG</span>
                        </div>
                        <span className="hidden sm:inline font-bold text-gray-900">AirGuard AI</span>
                    </Link>

                    {/* Desktop Navigation */}
                    <nav className="hidden md:flex items-center gap-6">
                        <Link to="/dashboard" className="text-gray-700 hover:text-green-600 transition">
                            Dashboard
                        </Link>
                        {user?.role !== 'viewer' && (
                            <Link to="/commands" className="text-gray-700 hover:text-green-600 transition">
                                Commands
                            </Link>
                        )}
                        {user?.role !== 'viewer' && (
                            <Link to="/reports" className="text-gray-700 hover:text-green-600 transition">
                                Reports
                            </Link>
                        )}
                        {user?.role !== 'viewer' && (
                            <Link to="/audit-logs" className="text-gray-700 hover:text-green-600 transition">
                                Audit Logs
                            </Link>
                        )}
                        {user?.role === 'admin' && (
                            <Link to="/settings" className="text-gray-700 hover:text-green-600 transition">
                                Settings
                            </Link>
                        )}
                    </nav>

                    {/* Right Side - User Menu */}
                    <div className="flex items-center gap-4">
                        {/* Language Selector */}
                        <select
                            value={language}
                            onChange={(e) => setLanguage(e.target.value)}
                            className="text-sm border border-gray-300 rounded px-2 py-1"
                        >
                            <option value="en">English</option>
                            <option value="hi">हिंदी</option>
                        </select>

                        {/* User Info and Logout */}
                        <div className="hidden sm:flex items-center gap-4">
                            <span className="text-sm text-gray-700">{user?.username}</span>
                            <button
                                onClick={handleLogout}
                                className="flex items-center gap-2 px-3 py-2 text-gray-700 hover:bg-gray-100 rounded-lg transition"
                            >
                                <LogOut size={18} />
                                <span className="hidden sm:inline">Logout</span>
                            </button>
                        </div>

                        {/* Mobile Menu Toggle */}
                        <button
                            onClick={() => setMenuOpen(!menuOpen)}
                            className="md:hidden p-2 hover:bg-gray-100 rounded-lg"
                        >
                            {menuOpen ? <X size={24} /> : <Menu size={24} />}
                        </button>
                    </div>
                </div>

                {/* Mobile Navigation */}
                {menuOpen && (
                    <nav className="md:hidden pb-4 border-t border-gray-200">
                        <Link to="/dashboard" className="block px-4 py-2 text-gray-700 hover:bg-gray-100">
                            Dashboard
                        </Link>
                        {user?.role !== 'viewer' && (
                            <>
                                <Link to="/commands" className="block px-4 py-2 text-gray-700 hover:bg-gray-100">
                                    Commands
                                </Link>
                                <Link to="/reports" className="block px-4 py-2 text-gray-700 hover:bg-gray-100">
                                    Reports
                                </Link>
                                <Link to="/audit-logs" className="block px-4 py-2 text-gray-700 hover:bg-gray-100">
                                    Audit Logs
                                </Link>
                            </>
                        )}
                        {user?.role === 'admin' && (
                            <Link to="/settings" className="block px-4 py-2 text-gray-700 hover:bg-gray-100">
                                Settings
                            </Link>
                        )}
                        <button
                            onClick={handleLogout}
                            className="block w-full text-left px-4 py-2 text-gray-700 hover:bg-gray-100"
                        >
                            Logout
                        </button>
                    </nav>
                )}
            </div>
        </header>
    );
}
